1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The closed set of insurable item types, each with its base premium in gold. */
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	} as const satisfies Record<string, number>;
54	
55	export type ItemType = keyof typeof BASE_PREMIUMS;
56	
57	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	
62	const distinctTypes = (items: Item[]): string[] => [...new Set(items.map((item) => item.type))];
63	
64	const groupByType = (items: Item[]): Item[][] =>
65	  distinctTypes(items).map((type) => items.filter((item) => item.type === type));
66	
67	const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);
68	
69	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
70	
71	/** Three alike components form a block, priced at a special base premium. */
72	const basePremiumOfGroup = (group: Item[]): number =>
73	  group.length === BLOCK_SIZE && group.every(isComponent)
74	    ? BLOCK_BASE_PREMIUM
75	    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);
76	
77	const totalBasePremium = (items: Item[]): number =>
78	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
79	
80	const CURSE_SURCHARGE_RATE = 0.5;
81	
82	/** Item-specific surcharges apply to the affected item's own base premium. */
83	const itemSurcharges = (items: Item[]): number =>
84	  items.reduce(
85	    (sum, item) => sum + (item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0),
86	    0,
87	  );
88	
89	const quotePremium = (items: Item[]): number => {
90	  const basePremium = totalBasePremium(items);
91	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
92	  return roundPremium(
93	    basePremium + itemSurcharges(items) + firstInsuranceSurcharge + PROCESSING_FEE,
94	  );
95	};
96	
97	const runStep = (step: Step): Result => {
98	  if (step.op === "quote") return { premium: quotePremium(step.items) };
99	  throw new Error(`Unsupported step: ${step.op}`);
100	};
101	
102	export const runScenario = (scenario: Scenario): { results: Result[] } => {
103	  return { results: scenario.steps.map(runStep) };
104	};
